  "lead": "纵向+多方验证切片：同一条时间线横跨明/朝鲜/日本三方。朝鲜方=宣祖昭敬大王修正实录（亲历官修）；清方=明史·李如松传（清修叙明事，作者党派=清）；日本方=日本外史（江户赖山阳汉文私修，学界质疑其史料价值——这本身是立场素材）。三方对碧蹄馆明军伤亡的数字（朝鲜『八十余人』/明史『喪失甚多』/日本『斬首一万』）构成教科书级冲突对。真正明方自著（明神宗实录等）无免费全文→显式缺口。",
